  2	import { getConfigPath } from '../utils/paths.js';
  3	import { readJsonFile, writeJsonFile, FileNotFoundError } from '../storage/json-storage.js';
  4	import type { AppConfig, GitCredentialEntry } from './config.types.js';
  5	import { toKebabCase } from '../utils/slug.js';
  6	import {
  7	    DEFAULT_NOTES_CARD_HEIGHT,
  8	    DEFAULT_NOTES_COLUMNS,
  9	    MIN_NOTES_CARD_HEIGHT,
 10	    MAX_NOTES_CARD_HEIGHT,
 11	    MIN_NOTES_COLUMNS,
 12	    MAX_NOTES_COLUMNS,
 13	    MIN_POLLING_INTERVAL_SECONDS,
 14	    MAX_POLLING_INTERVAL_SECONDS,
 15	    MIN_CLONE_DEPTH,
 16	    MAX_CLONE_DEPTH,
 17	    MIN_SERVER_PORT,
 18	    MAX_SERVER_PORT,
 19	    MAX_CREDENTIAL_ID_LENGTH,
 20	    MAX_CREDENTIAL_LABEL_LENGTH,
 21	    MAX_CREDENTIAL_HOST_LENGTH,
 22	    MAX_CREDENTIAL_TOKEN_LENGTH,
 23	} from './config.constants.js';
 24	
 25	const REQUIRED_FIELDS: ReadonlyArray<keyof AppConfig> = ['projectsFolder', 'storageFolder'];
 26	
 27	// When adding a new non-optional AppConfig field with a sensible default: add the
 28	// key to the Pick<AppConfig, ...> union and its value here, then update loadConfig()
 29	// to fall back to it. The satisfies guard below will catch if DEFAULTS is incomplete.
 30	export const DEFAULTS: Readonly<Pick<AppConfig, 'cloneDepth' | 'serverPort' | 'gitPollingIntervalSeconds' | 'notesCardHeight' | 'notesColumns'>> = {
 31	    cloneDepth: 50,
 32	    serverPort: 4200,
 33	    gitPollingIntervalSeconds: 30,
 34	    notesCardHeight: DEFAULT_NOTES_CARD_HEIGHT,
 35	    notesColumns: DEFAULT_NOTES_COLUMNS,
 36	};
 37	
 38	// Compile-time guard: ensures DEFAULTS + required fields cover the full AppConfig shape.
 39	// If a new required field is added to AppConfig without updating DEFAULTS, this line
 40	// will produce a type error.
 41	const _defaultsCoverageGuard: AppConfig = {
 42	    ...DEFAULTS,
 43	    projectsFolder: '',
 44	    storageFolder: '',
 45	} satisfies AppConfig;
 46	void _defaultsCoverageGuard;
 47	
 48	/**
 49	 * Loads, validates, and returns the application configuration from `config.json`.
 50	 *
 51	 * **Setup:** Copy `config.dist.json` to `config.json` and fill in the required
 52	 * fields before running the tool.
 53	 *
 54	 * @param configPath Optional absolute path to the config file. Defaults to the
 55	 *   `config.json` in the tool root. Pass a custom path in tests to avoid touching
 56	 *   the real config file.
 57	 * @throws {Error} If `config.json` does not exist (with instruction to copy from
 58	 *   `config.dist.json`).
 59	 * @throws {Error} If any required field is missing, non-string, or empty.
 60	 */
 61	export function loadConfig(configPath?: string): AppConfig {
 62	    const resolvedConfigPath = configPath ?? getConfigPath();
 63	    let raw: Record<string, unknown>;
 64	
 65	    try {
 66	        raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
 67	    } catch (err) {
 68	        if (err instanceof FileNotFoundError) {
 69	            throw new Error(
 70	                `config.json not found at "${resolvedConfigPath}". ` +
 71	                `Copy config.dist.json to config.json and fill in the required fields.`
 72	            );
 73	        }
 74	        throw err;
 75	    }
 76	
 77	    for (const field of REQUIRED_FIELDS) {
 78	        const value = raw[field];
 79	        if (typeof value !== 'string' || value.trim() === '') {
 80	            throw new Error(
 81	                `Configuration error: required field "${field}" must be a non-empty string in config.json.`
 82	            );
 83	        }
 84	    }
 85	
 86	    return {
 87	        projectsFolder: raw['projectsFolder'] as string,
 88	        storageFolder: raw['storageFolder'] as string,
 89	        cloneDepth: parseIntegerField(raw['cloneDepth'], 'cloneDepth', DEFAULTS.cloneDepth, MIN_CLONE_DEPTH, MAX_CLONE_DEPTH),
 90	        serverPort: parseIntegerField(raw['serverPort'], 'serverPort', DEFAULTS.serverPort, MIN_SERVER_PORT, MAX_SERVER_PORT),
 91	        gitPollingIntervalSeconds: parseIntegerField(
 92	            raw['gitPollingIntervalSeconds'],
 93	            'gitPollingIntervalSeconds',
 94	            DEFAULTS.gitPollingIntervalSeconds,
 95	            MIN_POLLING_INTERVAL_SECONDS,
 96	            MAX_POLLING_INTERVAL_SECONDS,
 97	        ),
 98	        gitCredentials: parseGitCredentials(raw['gitCredentials']),
 99	        webserverUrl: typeof raw['webserverUrl'] === 'string' && raw['webserverUrl'].trim() !== ''
100	            ? raw['webserverUrl'].trim().replace(/\/+$/, '')

101	            : undefined,
102	        notesCardHeight: parseIntegerField(
103	            raw['notesCardHeight'],
104	            'notesCardHeight',
105	            DEFAULTS.notesCardHeight,
106	            MIN_NOTES_CARD_HEIGHT,
107	            MAX_NOTES_CARD_HEIGHT,
108	        ),
109	        notesColumns: parseIntegerField(
110	            raw['notesColumns'],
111	            'notesColumns',
112	            DEFAULTS.notesColumns,
113	            MIN_NOTES_COLUMNS,
114	            MAX_NOTES_COLUMNS,
115	        ),
116	    };
117	}
118	
119	/**
120	 * Parses a numeric config field, enforcing integer-only values and optional
121	 * `[min, max]` range bounds.
122	 *
123	 * - If `value` is not a `number`, returns `defaultValue`.
124	 * - If `value` is a number but not an integer (e.g. a float like `220.5`),
125	 *   returns `defaultValue`.
126	 * - If `min` and `max` are provided and the integer value is outside that range,
127	 *   emits `console.warn` but returns the value as-is (no clamping).
128	 *
129	 * @param value     Raw value read from the config file.
130	 * @param fieldName Field name used in warning messages.
131	 * @param defaultValue Fallback value for non-numeric or float inputs.
132	 * @param min       Optional lower bound (inclusive).
133	 * @param max       Optional upper bound (inclusive).
134	 */
135	function parseIntegerField(
136	    value: unknown,
137	    fieldName: string,
138	    defaultValue: number,
139	    min?: number,
140	    max?: number,
141	): number {
142	    if (typeof value !== 'number') {
143	        return defaultValue;
144	    }
145	    if (!Number.isInteger(value)) {
146	        return defaultValue;
147	    }
148	    if (min !== undefined && max !== undefined && (value < min || value > max)) {
149	        console.warn(
150	            `Configuration warning: "${fieldName}" value ${value} is outside the allowed range ` +
151	            `[${min}, ${max}]. The value will be used as-is.`
152	        );
153	    }
154	    return value;
155	}
156	
157	/**
158	 * Validates and returns the `gitCredentials` value from the raw config,
159	 * auto-migrating the legacy `Record<string, string>` format to the new
160	 * `GitCredentialEntry[]` format when necessary.
161	 *
162	 * **Accepted inputs:**
163	 * - `undefined` / `null` → returns `undefined`
164	 * - `GitCredentialEntry[]` (new format) → validated and returned as-is
165	 * - `Record<string, string>` (old format, hostname→token map) → migrated to
166	 *   `GitCredentialEntry[]` with `id` derived from the hostname in kebab-case
167	 *   and `label` set to the hostname. Colliding IDs get a numeric suffix (`-2`,
168	 *   `-3`, …).
169	 * - An empty array `[]` → returns `[]`
170	 *
171	 * **Validation (new-format arrays):**
172	 * - Every entry must have non-empty `id`, `label`, `host`, and `token` fields.
173	 * - Duplicate `id` values within the array are rejected.
174	 *
175	 * @returns `undefined` when the field is absent or null; otherwise a
176	 *   `GitCredentialEntry[]` (possibly empty).
177	 * @throws {Error} If the value is present but structurally invalid, or if any
178	 *   entry fails validation.
179	 */
180	function parseGitCredentials(value: unknown): GitCredentialEntry[] | undefined {
181	    if (value === undefined || value === null) {
182	        return undefined;
183	    }
184	
185	    // --- New format: array of GitCredentialEntry objects ---
186	    if (Array.isArray(value)) {
187	        // Empty array is valid — treat as "no credentials".
188	        if (value.length === 0) {
189	            return [];
190	        }
191	
192	        const seenIds = new Set<string>();
193	
194	        for (let i = 0; i < value.length; i++) {
195	            const entry = value[i] as Record<string, unknown>;
196	
197	            if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
198	                throw new Error(
199	                    `Configuration error: gitCredentials[${i}] must be a credential object, got ${typeof entry}.`
200	                );
201	            }
202	
203	            for (const field of ['id', 'label', 'host', 'token'] as const) {
204	                const fieldValue = entry[field];
205	                if (typeof fieldValue !== 'string' || fieldValue.trim() === '') {
206	                    throw new Error(
207	                        `Configuration error: gitCredentials[${i}].${field} must be a non-empty string.`
208	                    );
209	                }
210	            }
211	
212	            // Per-field length limits — enforce the same limits as the credential API.
213	            const fieldLimits: Array<['id' | 'label' | 'host' | 'token', number]> = [
214	                ['id', MAX_CREDENTIAL_ID_LENGTH],
215	                ['label', MAX_CREDENTIAL_LABEL_LENGTH],
216	                ['host', MAX_CREDENTIAL_HOST_LENGTH],
217	                ['token', MAX_CREDENTIAL_TOKEN_LENGTH],
218	            ];
219	            for (const [field, maxLen] of fieldLimits) {
220	                const fieldValue = (entry[field] as string).trim();
221	                if (fieldValue.length > maxLen) {
222	                    throw new Error(
223	                        `Configuration error: gitCredentials[${i}].${field} must not exceed ${maxLen} characters (got ${fieldValue.length}).`
224	                    );
225	                }
226	            }
227	
228	            const id = (entry['id'] as string).trim();
229	            if (seenIds.has(id)) {
230	                throw new Error(
231	                    `Configuration error: gitCredentials contains duplicate id "${id}".`
232	                );
233	            }
234	            seenIds.add(id);
235	        }
236	
237	        // Trim all four fields on every entry before returning so that
238	        // downstream consumers always receive normalized values.
239	        return (value as Array<Record<string, unknown>>).map(entry => ({
240	            id: (entry['id'] as string).trim(),
241	            label: (entry['label'] as string).trim(),
242	            host: (entry['host'] as string).trim(),
243	            token: (entry['token'] as string).trim(),
244	        })) as GitCredentialEntry[];
245	    }
246	
247	    // --- Old format: plain object mapping hostname → token ---
248	    if (typeof value === 'object') {
249	        const legacyMap = value as Record<string, unknown>;
250	        const entries = Object.entries(legacyMap);
251	
252	        // Empty legacy object → return undefined (no credentials configured).
253	        if (entries.length === 0) {
254	            return undefined;
255	        }
256	
257	        const result: GitCredentialEntry[] = [];
258	        const usedIds = new Set<string>();
259	
260	        for (const [index, [host, token]] of entries.entries()) {
261	            if (typeof token !== 'string') {
262	                throw new Error(
263	                    `Configuration error: gitCredentials entry #${index + 1} (legacy format) must have a string value, got ${typeof token}.`
264	                );
265	            }
266	            if (token === '') {
267	                throw new Error(
268	                    `Configuration error: gitCredentials entry #${index + 1} (legacy format) must not have an empty string value.`
269	                );
270	            }
271	
272	            // Derive a kebab-case ID from the hostname.
273	            const baseId = toKebabCase(host);
274	            let candidateId = baseId;
275	            let suffix = 2;
276	            while (usedIds.has(candidateId)) {
277	                candidateId = `${baseId}-${suffix}`;
278	                suffix++;
279	            }
280	            usedIds.add(candidateId);
281	
282	            result.push({
283	                id: candidateId,
284	                label: host,
285	                host: host.trim(),
286	                token: token.trim(),
287	            });
288	        }
289	
290	        return result;
291	    }
292	
293	    throw new Error(
294	        'Configuration error: "gitCredentials" must be an array of credential entries or omitted.'
295	    );
296	}
